namespace bgiplayer {
void SoundSubsystem::update_fade(FadeState& fade, uint32_t now_ms) {
    if (!fade.active) {
        return;
    }
    const int32_t span = static_cast<int32_t>(
        fade.deadline_ms - fade.start_ms);
    double ratio =
        span < 1
            ? 1.0
            : static_cast<double>(
                  static_cast<int32_t>(now_ms - fade.start_ms)) /
                  static_cast<double>(span);
    if (ratio >= 1.0) {
        fade.active = false;
        ratio = 1.0;
    }
    fade.current = static_cast<uint32_t>(
        static_cast<double>(
            static_cast<int32_t>(fade.to - fade.from)) *
            ratio +
        static_cast<double>(fade.from));
}
}  // namespace bgiplayer
